python3 - <<EOF
import os, filecmp, py_compile
t=os.environ["TARGET_DIR"]; o=os.environ["ORIGINAL_DIR"]
for d,_,fs in os.walk(t):
    for f in fs:
        if f.endswith(".py"):
            p=os.path.join(d,f); rel=os.path.relpath(p,t); q=os.path.join(o,rel)
            if not os.path.exists(q) or not filecmp.cmp(p,q,shallow=False):
                py_compile.compile(p,doraise=True)
print("Syntax: OK")
EOF

